                candidate.m_waterWalking = 1;
                cost = calcTerrainCost(srcCell, direction, turnMobility,
                                       pathfinding, destCell->m_roadSet,
                                       candidate.m_flying ? m_flightLevel : -1,
                                       m_waterWalkLevel, nativeTerrain,
                                       hasNomad);
